"use client";

import { type PointerEvent as ReactPointerEvent, useEffect, useRef, useState } from "react";
import { type TimelineEdge, type TimelineItem, type TimelineTrack, itemEdges, itemEnd, itemStart, moveItems, resizeClip, roundTime, sameItems, snapDelta } from "./animation-timeline-math";
import { type AnimationTimelineDetail, useIsomorphicLayoutEffect } from "./animation-timeline-state";

type Options = {
  items: TimelineItem[];
  tracks: TimelineTrack[];
  selection: string[];
  duration: number;
  currentTime: number;
  snap: boolean;
  snapInterval: number;
  pixelsPerSecond: number;
  minClipDuration: number;
  scrollerRef: { current: HTMLDivElement | null };
  namesRef: { current: HTMLDivElement | null };
  laneRef: { current: HTMLDivElement | null };
  isEditable: (item: TimelineItem) => boolean;
  setLive: (items: TimelineItem[] | null) => void;
  onSelectionChange: (ids: string[]) => void;
  onItemsChange?: (items: TimelineItem[], detail: AnimationTimelineDetail) => void;
  onItemsCommit: (items: TimelineItem[], detail: AnimationTimelineDetail) => void;
};

type Drag = {
  pointerId: number;
  id: string;
  edge?: TimelineEdge;
  ids: string[];
  shift: boolean;
  wasSelected: boolean;
  armed: boolean;
  moved: boolean;
  alt: boolean;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  startOffsetY: number;
  startTime: number;
  startItems: TimelineItem[];
  last: TimelineItem[];
  targets: number[];
  edges: number[];
  stop: () => void;
};

const touchHold = 250;
const touchSlop = 8;
const dragThreshold = 3;
const snapPixels = 6;
const edgeZone = 32;
const edgeSpeed = 10;

/** Press and drag items. Touch waits for a short hold so scrolling never moves a clip. Escape cancels. */
export function useTimelineDrag(options: Options) {
  const latest = useRef(options);
  useIsomorphicLayoutEffect(() => {
    latest.current = options;
  });
  const active = useRef<Drag | null>(null);
  const suppressClick = useRef(false);
  const [draggingIds, setDraggingIds] = useState<string[]>([]);
  const [armedId, setArmedId] = useState<string | null>(null);
  const [guide, setGuide] = useState<number | null>(null);

  const detailOf = (drag: Drag): AnimationTimelineDetail => ({ action: drag.edge ? "resize" : "move", ids: drag.ids });

  const timeAt = (clientX: number) => {
    const { laneRef, pixelsPerSecond } = latest.current;
    const left = laneRef.current?.getBoundingClientRect().left ?? 0;
    return (clientX - left) / pixelsPerSecond;
  };

  const applyPress = (drag: Drag) => {
    const { selection, onSelectionChange } = latest.current;
    if (drag.wasSelected) return;
    onSelectionChange(drag.shift ? [...selection, drag.id] : [drag.id]);
  };

  const apply = () => {
    const drag = active.current;
    if (!drag?.moved) return;
    const { laneRef, tracks, duration, snap, snapInterval, pixelsPerSecond, minClipDuration, setLive, onItemsChange } = latest.current;
    const raw = timeAt(drag.lastX) - drag.startTime;
    const found = snap && !drag.alt ? snapDelta(drag.edges.map((edge) => edge + raw), drag.targets, snapInterval, snapPixels / pixelsPerSecond) : null;
    const delta = raw + (found?.delta ?? 0);
    let next: TimelineItem[];
    if (drag.edge) {
      next = resizeClip(drag.startItems, drag.id, drag.edge, delta, minClipDuration, duration);
    } else {
      const rect = laneRef.current?.getBoundingClientRect();
      const rowHeight = rect && tracks.length ? rect.height / tracks.length : 0;
      const shift = rect && rowHeight ? Math.round((drag.lastY - rect.top - drag.startOffsetY) / rowHeight) : 0;
      next = moveItems(drag.startItems, drag.ids, delta, shift, tracks, duration);
    }
    setGuide(found ? roundTime(found.at) : null);
    if (sameItems(next, drag.last)) return;
    drag.last = next;
    setLive(next);
    onItemsChange?.(next, detailOf(drag));
  };

  const finish = (commit: boolean) => {
    const drag = active.current;
    if (!drag) return;
    active.current = null;
    drag.stop();
    setDraggingIds([]);
    setArmedId(null);
    setGuide(null);
    const { selection, setLive, onSelectionChange, onItemsChange, onItemsCommit } = latest.current;
    if (drag.moved) {
      suppressClick.current = true;
      window.setTimeout(() => {
        suppressClick.current = false;
      }, 0);
      setLive(null);
      if (commit && !sameItems(drag.last, drag.startItems)) onItemsCommit(drag.last, detailOf(drag));
      else if (!sameItems(drag.last, drag.startItems)) onItemsChange?.(drag.startItems, detailOf(drag));
      return;
    }
    if (!commit) return;
    if (!drag.armed) applyPress(drag);
    if (drag.wasSelected && drag.shift) onSelectionChange(selection.filter((id) => id !== drag.id));
    else if (drag.wasSelected && selection.length > 1) onSelectionChange([drag.id]);
  };

  const begin = (event: ReactPointerEvent<HTMLElement>, item: TimelineItem, edge?: TimelineEdge) => {
    const { items, selection, isEditable, currentTime, duration, laneRef } = latest.current;
    if (event.button !== 0 || event.ctrlKey || active.current || !isEditable(item)) return;
    event.stopPropagation();
    const wasSelected = selection.includes(item.id);
    const selected = items.filter((candidate) => selection.includes(candidate.id) && isEditable(candidate)).map((candidate) => candidate.id);
    const ids = edge ? [item.id] : wasSelected ? selected : event.shiftKey ? [...selected, item.id] : [item.id];
    const moving = items.filter((candidate) => ids.includes(candidate.id));
    const edges = edge ? [edge === "start" ? itemStart(item) : itemEnd(item)] : moving.flatMap(itemEdges);
    const others = items.filter((candidate) => !ids.includes(candidate.id)).flatMap(itemEdges);
    const element = event.currentTarget;
    const pointerId = event.pointerId;
    const holdFirst = event.pointerType === "touch" && !edge;
    let frame = 0;
    let timer = 0;

    const onMove = (next: PointerEvent) => {
      const drag = active.current;
      if (!drag || next.pointerId !== pointerId) return;
      drag.lastX = next.clientX;
      drag.lastY = next.clientY;
      drag.alt = next.altKey;
      const distance = Math.hypot(next.clientX - drag.startX, next.clientY - drag.startY);
      if (!drag.armed) {
        if (distance > touchSlop) finish(false);
        return;
      }
      if (!drag.moved) {
        if (distance < dragThreshold) return;
        drag.moved = true;
        setDraggingIds(drag.ids);
        frame = requestAnimationFrame(tick);
      }
      apply();
    };
    const tick = () => {
      const drag = active.current;
      const { scrollerRef, namesRef } = latest.current;
      const scroller = scrollerRef.current;
      if (!drag || !scroller) return;
      const rect = scroller.getBoundingClientRect();
      const left = rect.left + (namesRef.current?.offsetWidth ?? 0) + edgeZone;
      const right = rect.right - edgeZone;
      const speed = drag.lastX < left ? -edgeSpeed : drag.lastX > right ? edgeSpeed : 0;
      const before = scroller.scrollLeft;
      if (speed) scroller.scrollLeft = before + speed;
      if (scroller.scrollLeft !== before) apply();
      frame = requestAnimationFrame(tick);
    };
    const onUp = (next: PointerEvent) => void (next.pointerId === pointerId && finish(true));
    const onCancel = (next: PointerEvent) => void (next.pointerId === pointerId && finish(false));
    const onKey = (next: KeyboardEvent) => {
      if (next.key !== "Escape") return;
      next.preventDefault();
      next.stopPropagation();
      finish(false);
    };
    const onBlur = () => finish(false);
    // Once a held finger is dragging, the page must not start scrolling.
    const onTouchMove = (next: TouchEvent) => {
      if (active.current?.armed) next.preventDefault();
    };
    const listening = new AbortController();
    const { signal } = listening;
    window.addEventListener("pointermove", onMove, { signal });
    window.addEventListener("pointerup", onUp, { signal });
    window.addEventListener("pointercancel", onCancel, { signal });
    window.addEventListener("keydown", onKey, { signal, capture: true });
    window.addEventListener("blur", onBlur, { signal });
    if (holdFirst) window.addEventListener("touchmove", onTouchMove, { signal, passive: false });

    const laneTop = laneRef.current?.getBoundingClientRect().top ?? 0;
    const drag: Drag = {
      pointerId,
      id: item.id,
      edge,
      ids,
      shift: event.shiftKey,
      wasSelected,
      armed: !holdFirst,
      moved: false,
      alt: event.altKey,
      startX: event.clientX,
      startY: event.clientY,
      lastX: event.clientX,
      lastY: event.clientY,
      startOffsetY: event.clientY - laneTop,
      startTime: timeAt(event.clientX),
      startItems: items,
      last: items,
      targets: [0, duration, currentTime, ...others],
      edges,
      stop: () => {
        cancelAnimationFrame(frame);
        window.clearTimeout(timer);
        listening.abort();
      },
    };
    active.current = drag;
    if (holdFirst) {
      timer = window.setTimeout(() => {
        drag.armed = true;
        setArmedId(item.id);
        applyPress(drag);
      }, touchHold);
      return;
    }
    applyPress(drag);
    try {
      element.setPointerCapture?.(pointerId);
    } catch {
      // The pointer may already have ended.
    }
  };

  useEffect(() => () => active.current?.stop(), []);

  return { begin, cancel: () => finish(false), draggingIds, armedId, guide, clickSuppressed: () => suppressClick.current };
}

"use client";

import { ContextMenu, ContextMenuContent, ContextMenuItem, ContextMenuTarget } from "@/components/ui/context-menu";
import { type TimelineEdge, type TimelineItem, itemEnd, itemStart } from "./animation-timeline-math";
import { useAnimationTimeline } from "./animation-timeline-state";
import { cn } from "@/lib/utils";

const minLabelWidth = 44;
const minDurationWidth = 96;

function EdgeHandle({ item, edge }: { item: TimelineItem; edge: TimelineEdge }) {
  const { beginDrag } = useAnimationTimeline();
  return (
    <span
      aria-hidden
      data-slot="animation-timeline-edge"
      data-edge={edge}
      // On touch, only the selected clip's edges take a press, so a tap on the clip never resizes it.
      // There they are 44px targets centered on the clip's edge.
      className={cn(
        "absolute inset-y-0 z-10 w-2 cursor-ew-resize touch-none after:absolute after:inset-y-1.5 after:w-0.5 after:rounded-full after:bg-current after:opacity-0 group-hover/item:after:opacity-50 group-data-selected/item:after:opacity-70 pointer-coarse:inset-y-auto pointer-coarse:top-1/2 pointer-coarse:h-11 pointer-coarse:w-11 pointer-coarse:-translate-y-1/2 pointer-coarse:after:inset-y-3.5 pointer-coarse:not-group-data-selected/item:pointer-events-none",
        edge === "start" ? "left-0 after:left-0.5 pointer-coarse:-left-5 pointer-coarse:after:left-[1.375rem]" : "right-0 after:right-0.5 pointer-coarse:-right-5 pointer-coarse:after:right-[1.375rem]",
      )}
      onPointerDown={(event) => beginDrag(event, item, edge)}
    />
  );
}

/** One clip or keyframe, placed by its time and track. */
export function AnimationTimelineItem({ item }: { item: TimelineItem }) {
  const { tracks, selection, pixelsPerSecond, draggingIds, armedId, container, disabled, messages, instructionsId, formatTime, isEditable, menuIds, beginDrag, cancelDrag, selectForMenu, onItemKeyDown, onDuplicate, onDelete } = useAnimationTimeline();
  const index = tracks.findIndex((track) => track.id === item.trackId);
  if (index < 0) return null;
  const track = tracks[index];
  const editable = isEditable(item);
  const selected = selection.includes(item.id);
  const clip = item.kind === "clip";
  const name = item.label ?? (clip ? messages.untitledClip : messages.untitledKeyframe);
  const left = itemStart(item) * pixelsPerSecond;
  const rowTop = (index / tracks.length) * 100;
  const rowHeight = 100 / tracks.length;
  const label = clip ? messages.clip(name, track.label, formatTime(itemStart(item)), formatTime(itemEnd(item))) : messages.keyframe(name, track.label, formatTime(itemStart(item)));
  const width = clip ? Math.max(item.duration * pixelsPerSecond, 8) : 0;
  const position = clip
    ? { left, width, top: `calc(${rowTop}% + 0.25rem)`, height: `calc(${rowHeight}% - 0.5rem)` }
    : { left: `clamp(0.75rem, ${left}px, calc(100% - 0.75rem))`, top: `${rowTop + rowHeight / 2}%` };

  return (
    <ContextMenu
      disabled={disabled || !editable || (!onDuplicate && !onDelete)}
      onOpenChange={(open) => {
        if (open) cancelDrag();
      }}
    >
      <ContextMenuTarget
        role="button"
        tabIndex={editable ? 0 : -1}
        aria-label={label}
        aria-pressed={selected}
        aria-disabled={!editable || undefined}
        aria-describedby={editable ? instructionsId : undefined}
        data-timeline-item={item.kind}
        data-selected={selected ? "" : undefined}
        data-dragging={draggingIds.includes(item.id) ? "" : undefined}
        data-armed={armedId === item.id ? "" : undefined}
        className={cn(
          "group/item absolute touch-pan-x touch-pan-y select-none focus-visible:not-data-pointer-focus:ring-2 focus-visible:not-data-pointer-focus:ring-ring [-webkit-touch-callout:none] data-dragging:z-[5] data-selected:z-[4]",
          editable ? "cursor-grab data-dragging:cursor-grabbing" : "cursor-not-allowed",
          track.hidden && "opacity-40",
          !editable && !track.hidden && "opacity-60",
          clip
            ? "flex items-center justify-between gap-2 rounded-[5px] bg-foreground/25 px-2 text-xs text-foreground transition-colors hover:bg-foreground/30 data-armed:ring-2 data-armed:ring-primary data-selected:bg-primary data-selected:text-primary-foreground hover:data-selected:bg-primary motion-reduce:transition-none dark:bg-foreground/85 dark:text-background dark:hover:bg-foreground dark:data-selected:bg-primary dark:data-selected:text-primary-foreground dark:hover:data-selected:bg-primary"
            : "grid size-6 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-sm pointer-coarse:size-11",
        )}
        style={position}
        // A click selects without the keyboard focus ring; the ring returns when focus next arrives by keyboard.
        onPointerDownCapture={(event) => {
          event.currentTarget.dataset.pointerFocus = "";
        }}
        onBlur={(event) => {
          delete event.currentTarget.dataset.pointerFocus;
        }}
        onPointerDown={(event) => beginDrag(event, item)}
        onKeyDown={(event) => onItemKeyDown(event, item)}
        onContextMenuCapture={() => selectForMenu(item)}
      >
        {clip ? (
          <>
            {width >= minLabelWidth && <span className="pointer-events-none min-w-0 truncate">{name}</span>}
            {width >= minDurationWidth && <span className="pointer-events-none shrink-0 font-mono text-[0.6875rem] tabular-nums opacity-80">{Number(item.duration.toFixed(2))}s</span>}
            {editable && <EdgeHandle item={item} edge="start" />}
            {editable && <EdgeHandle item={item} edge="end" />}
          </>
        ) : (
          <span aria-hidden className="size-2.5 rotate-45 rounded-[2px] bg-foreground/70 transition-transform group-hover/item:scale-125 group-data-armed/item:scale-125 group-data-selected/item:bg-primary group-data-selected/item:ring-2 group-data-selected/item:ring-primary/30 motion-reduce:transition-none" />
        )}
      </ContextMenuTarget>
      <ContextMenuContent container={container} positionMethod={container ? "fixed" : undefined}>
        {onDuplicate && <ContextMenuItem onClick={() => onDuplicate(menuIds(item))}>{messages.duplicate}</ContextMenuItem>}
        {onDelete && (
          <ContextMenuItem variant="destructive" onClick={() => onDelete(menuIds(item))}>
            {messages.delete}
          </ContextMenuItem>
        )}
      </ContextMenuContent>
    </ContextMenu>
  );
}

export type TimelineTrack = { id: string; label: string; hidden?: boolean; locked?: boolean };
export type TimelineClip = { id: string; kind: "clip"; trackId: string; start: number; duration: number; label?: string };
export type TimelineKeyframe = { id: string; kind: "keyframe"; trackId: string; time: number; label?: string };
export type TimelineItem = TimelineClip | TimelineKeyframe;
export type TimelineEdge = "start" | "end";

export const defaultPixelsPerSecond = 80;

const rulerSteps = [0.05, 0.1, 0.25, 0.5, 1, 2, 5, 10, 15, 30, 60, 120, 300, 600];
const smallestLabelGap = 72;
const smallestTickGap = 10;

const clamp = (value: number, low: number, high: number) => Math.min(high, Math.max(low, value));
export const roundTime = (time: number) => Math.round(time * 100) / 100;
export const itemStart = (item: TimelineItem) => (item.kind === "clip" ? item.start : item.time);
export const itemEnd = (item: TimelineItem) => (item.kind === "clip" ? item.start + item.duration : item.time);
export const itemEdges = (item: TimelineItem) => (item.kind === "clip" ? [item.start, item.start + item.duration] : [item.time]);

/** Labelled marks far enough apart to read, and the smaller ticks between them. */
export function rulerScale(pixelsPerSecond: number) {
  const major = rulerSteps.find((step) => step * pixelsPerSecond >= smallestLabelGap) ?? rulerSteps[rulerSteps.length - 1];
  const divisions = [5, 2].find((count) => (major * pixelsPerSecond) / count >= smallestTickGap) ?? 1;
  return { major, minor: major / divisions };
}

export function rulerMarks(duration: number, major: number) {
  const count = Math.floor(duration / major + 1e-6);
  return Array.from({ length: count + 1 }, (_, index) => roundTime(index * major));
}

export function formatRulerTime(time: number, major: number) {
  if (time < 60 && major < 60) return `${Number(time.toFixed(2))}s`;
  const minutes = Math.floor(time / 60);
  return `${minutes}:${String(Math.round(time - minutes * 60)).padStart(2, "0")}`;
}

/** The smallest shift that puts one candidate on a target or a ruler tick, if any is close enough. */
export function snapDelta(candidates: number[], targets: number[], interval: number, threshold: number) {
  let best: { delta: number; at: number } | null = null;
  const consider = (candidate: number, at: number) => {
    const delta = at - candidate;
    if (Math.abs(delta) <= threshold && (!best || Math.abs(delta) < Math.abs(best.delta))) best = { delta, at };
  };
  for (const candidate of candidates) {
    for (const target of targets) consider(candidate, target);
    if (interval > 0) consider(candidate, Math.round(candidate / interval) * interval);
  }
  return best as { delta: number; at: number } | null;
}

/** Moves items together in time and across tracks. The group keeps its shape at the limits. */
export function moveItems(items: TimelineItem[], ids: string[], delta: number, trackShift: number, tracks: TimelineTrack[], duration: number) {
  const moving = items.filter((item) => ids.includes(item.id));
  if (!moving.length) return items;
  const earliest = Math.min(...moving.map(itemStart));
  const latest = Math.max(...moving.map(itemEnd));
  const applied = clamp(delta, -earliest, duration - latest);
  const position = new Map(tracks.map((track, index) => [track.id, index]));
  const destination = (item: TimelineItem) => tracks[(position.get(item.trackId) ?? -1) + trackShift];
  const shift = trackShift !== 0 && moving.every((item) => destination(item) && !destination(item).locked);
  return items.map((item) => {
    if (!ids.includes(item.id)) return item;
    const trackId = shift ? destination(item).id : item.trackId;
    return item.kind === "clip" ? { ...item, trackId, start: roundTime(item.start + applied) } : { ...item, trackId, time: roundTime(item.time + applied) };
  });
}

/** Moves one edge of a clip, keeping the other edge where it is. */
export function resizeClip(items: TimelineItem[], id: string, edge: TimelineEdge, delta: number, minimum: number, duration: number) {
  return items.map((item) => {
    if (item.id !== id || item.kind !== "clip") return item;
    const end = item.start + item.duration;
    if (edge === "start") {
      const start = roundTime(clamp(item.start + delta, 0, end - minimum));
      return { ...item, start, duration: roundTime(end - start) };
    }
    return { ...item, duration: roundTime(clamp(item.duration + delta, minimum, duration - item.start)) };
  });
}

export function sameItems(a: TimelineItem[], b: TimelineItem[]) {
  return a.length === b.length && a.every((item, index) => {
    const other = b[index];
    return item.id === other.id && item.trackId === other.trackId && itemStart(item) === itemStart(other) && itemEnd(item) === itemEnd(other);
  });
}

"use client";

import { type KeyboardEvent, forwardRef, useEffect, useId, useRef, useState } from "react";
import { formatPlaybackTime } from "@/components/ui/playback-controls";
import { useTimelineDrag } from "./animation-timeline-drag";
import { type TimelineItem, defaultPixelsPerSecond, moveItems, resizeClip, rulerScale, sameItems } from "./animation-timeline-math";
import { AnimationTimelineBody } from "./animation-timeline-tracks";
import { AnimationTimelineToolbar } from "./animation-timeline-toolbar";
import { type AnimationTimelineDetail, type AnimationTimelineProps, AnimationTimelineContext, defaultMessages, defaultZoomLevels } from "./animation-timeline-state";
import { useTimelineScrub, useTimelineZoom } from "./animation-timeline-view";
import { cn } from "@/lib/utils";

/** Arranges clips and keyframes on tracks over time. Your app owns the data and runs playback. */
export const AnimationTimeline = forwardRef<HTMLDivElement, AnimationTimelineProps>(function AnimationTimeline(
  {
    label,
    tracks,
    items,
    duration,
    selection,
    onSelectionChange,
    onItemsCommit,
    onItemsChange,
    currentTime,
    onSeekCommit,
    onSeek,
    playing,
    onPlayingChange,
    loop,
    onLoopChange,
    onTrackHiddenChange,
    onTrackLockedChange,
    onDuplicate,
    onDelete,
    step = 0.1,
    largeStep = 1,
    minClipDuration = 0.1,
    snap = true,
    pixelsPerSecond: basePixels = defaultPixelsPerSecond,
    defaultZoom = "fit",
    zoomLevels = defaultZoomLevels,
    maxZoom = 800,
    formatTime = formatPlaybackTime,
    container,
    disabled = false,
    messages: messageOverrides,
    className,
    children,
    ...props
  },
  ref,
) {
  const messages = { ...defaultMessages, ...messageOverrides };
  const instructionsId = useId();
  const scrollerRef = useRef<HTMLDivElement | null>(null);
  const namesRef = useRef<HTMLDivElement | null>(null);
  const laneRef = useRef<HTMLDivElement | null>(null);
  const [liveItems, setLiveItems] = useState<TimelineItem[] | null>(null);
  const [liveTime, setLiveTime] = useState<number | null>(null);
  const { zoom, pixelsPerSecond, setZoom } = useTimelineZoom({ initial: defaultZoom, max: maxZoom, duration, basePixels, hasTracks: tracks.length > 0, scrollerRef, namesRef, laneRef });
  const { major, minor } = rulerScale(pixelsPerSecond);
  const shownItems = liveItems ?? items;
  const time = liveTime ?? currentTime;

  const trackOf = (item: TimelineItem) => tracks.find((track) => track.id === item.trackId);
  const isEditable = (item: TimelineItem) => !disabled && !trackOf(item)?.locked;
  const editableIds = (ids: string[]) => items.filter((item) => ids.includes(item.id) && isEditable(item)).map((item) => item.id);
  const menuIds = (item: TimelineItem) => (selection.includes(item.id) ? editableIds(selection) : [item.id]);

  const drag = useTimelineDrag({ items, tracks, selection, duration, currentTime, snap, snapInterval: minor, pixelsPerSecond, minClipDuration, scrollerRef, namesRef, laneRef, isEditable, setLive: setLiveItems, onSelectionChange, onItemsChange, onItemsCommit });
  const scrub = useTimelineScrub({ time: currentTime, duration, items, snap, snapInterval: minor, step, largeStep, pixelsPerSecond, disabled, laneRef, setLive: setLiveTime, onSeek, onSeekCommit });

  // Keeps the playhead in view while playing.
  useEffect(() => {
    const scroller = scrollerRef.current;
    if (!playing || !scroller) return;
    const names = namesRef.current?.offsetWidth ?? 0;
    const x = names + time * pixelsPerSecond;
    if (x < scroller.scrollLeft + names || x > scroller.scrollLeft + scroller.clientWidth - 12) scroller.scrollLeft = x - names - 12;
  }, [playing, time, pixelsPerSecond]);

  const edit = (next: TimelineItem[], detail: AnimationTimelineDetail) => {
    if (sameItems(next, items)) return;
    onItemsChange?.(next, detail);
    onItemsCommit(next, detail);
  };

  const onItemKeyDown = (event: KeyboardEvent<HTMLElement>, item: TimelineItem) => {
    if (!isEditable(item) || event.defaultPrevented) return;
    const selected = selection.includes(item.id);
    const ids = selected ? editableIds(selection) : [item.id];
    const amount = event.shiftKey && !event.altKey ? largeStep : step;
    const across = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0;
    const down = event.key === "ArrowDown" ? 1 : event.key === "ArrowUp" ? -1 : 0;
    const command = event.metaKey || event.ctrlKey;
    const handled = () => {
      event.preventDefault();
      event.stopPropagation();
      if (!selected) onSelectionChange([item.id]);
    };
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      if (event.shiftKey) onSelectionChange(selected ? selection.filter((id) => id !== item.id) : [...selection, item.id]);
      else onSelectionChange([item.id]);
    } else if (event.key === "Escape" && selection.length) {
      event.preventDefault();
      onSelectionChange([]);
    } else if ((event.key === "Delete" || event.key === "Backspace") && onDelete) {
      handled();
      onDelete(ids);
    } else if (command && event.key.toLowerCase() === "d" && onDuplicate) {
      handled();
      onDuplicate(ids);
    } else if (across && event.altKey) {
      if (item.kind !== "clip") return;
      handled();
      edit(resizeClip(items, item.id, event.shiftKey ? "start" : "end", across * step, minClipDuration, duration), { action: "resize", ids: [item.id] });
    } else if ((across || down) && !command) {
      handled();
      edit(moveItems(items, ids, across * amount, down, tracks, duration), { action: "move", ids });
    }
  };

  return (
    <AnimationTimelineContext.Provider
      value={{
        label,
        tracks,
        items: shownItems,
        duration,
        selection,
        playing,
        onPlayingChange,
        loop,
        onLoopChange,
        onTrackHiddenChange,
        onTrackLockedChange,
        onDuplicate,
        onDelete,
        container,
        time,
        disabled,
        step,
        largeStep,
        zoom,
        zoomLevels,
        pixelsPerSecond,
        major,
        minor,
        guide: drag.guide,
        draggingIds: drag.draggingIds,
        armedId: drag.armedId,
        scrubbing: scrub.scrubbing,
        messages,
        instructionsId,
        formatTime,
        scrollerRef,
        namesRef,
        laneRef,
        setZoom,
        seek: (next) => onSeek?.(next),
        commitSeek: onSeekCommit,
        isEditable,
        menuIds,
        beginDrag: drag.begin,
        cancelDrag: drag.cancel,
        selectForMenu: (item) => {
          if (isEditable(item) && !selection.includes(item.id)) onSelectionChange([item.id]);
        },
        onItemKeyDown,
        onLaneClick: (target, shift) => {
          if (!disabled && !shift && !drag.clickSuppressed() && !target.closest("[data-timeline-item]") && selection.length) onSelectionChange([]);
        },
        rulerHandlers: scrub.handlers,
      }}
    >
      <div ref={ref} role="group" aria-label={label} data-slot="animation-timeline" data-disabled={disabled ? "" : undefined} className={cn("@container/timeline grid w-full min-w-0 content-start gap-2 text-sm", className)} {...props}>
        {children ?? (
          <>
            <AnimationTimelineToolbar />
            <AnimationTimelineBody />
          </>
        )}
      </div>
    </AnimationTimelineContext.Provider>
  );
});

